import re

# Read the registry file
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_8/projects/acr-vla-conformal-refinement/registry.yaml', 'r') as f:
    lines = f.readlines()

# Find experiments and extract key info
current_exp = None
results = {}
for i, line in enumerate(lines):
    # Check for experiment header
    exp_match = re.match(r'^  (eval-[^:]*vla[_-]only[^:]*?):', line)
    if exp_match:
        current_exp = exp_match.group(1)
        results[current_exp] = {
            'status': None,
            'conclusion': None,
            'sr': None,
            'line': i
        }
    elif current_exp and line.strip().startswith('status:'):
        status_match = re.search(r'status:\s*(\S+)', line)
        if status_match:
            results[current_exp]['status'] = status_match.group(1)
    elif current_exp and line.strip().startswith('success_rate:'):
        sr_match = re.search(r'success_rate:\s*([0-9.]+)', line)
        if sr_match:
            results[current_exp]['sr'] = sr_match.group(1)
    elif current_exp and 'sr:' in line and not line.strip().startswith('#'):
        sr_match = re.search(r'sr:\s*([0-9.]+)', line)
        if sr_match:
            results[current_exp]['sr'] = sr_match.group(1)

# Organize by benchmark
by_benchmark = {'object': {}, 'spatial': {}, 'goal': {}, 'long': {}}

for exp_id, info in sorted(results.items()):
    if 'object' in exp_id and 'spatial' not in exp_id:
        by_benchmark['object'][exp_id] = info
    elif 'spatial' in exp_id:
        by_benchmark['spatial'][exp_id] = info
    elif 'goal' in exp_id:
        by_benchmark['goal'][exp_id] = info
    elif 'long' in exp_id:
        by_benchmark['long'][exp_id] = info

# Print summary
for benchmark in ['object', 'spatial', 'goal', 'long']:
    print(f"\n{'='*90}")
    print(f"BENCHMARK: {benchmark.upper()}")
    print(f"{'='*90}")

    exps = by_benchmark[benchmark]
    unique_seeds = set()

    for exp_id in sorted(exps.keys()):
        info = exps[exp_id]
        seed_match = re.search(r'seed(\d+)', exp_id)
        seed = seed_match.group(1) if seed_match else '?'
        if seed != '?':
            unique_seeds.add(seed)

        status = info['status'] if info['status'] else '?'
        sr = info['sr'] if info['sr'] else '?'
        print(f"  {exp_id:45} | Status: {status:8} | SR: {sr}")

    print(f"\n  Total: {len(exps)} experiments | Unique seeds: {len(unique_seeds)} ({sorted([int(s) for s in unique_seeds])})")

