python3 << 'EOF'
import re

# Read and parse more carefully
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_8/projects/acr-vla-conformal-refinement/registry.yaml', 'r') as f:
    lines = f.readlines()

# Track all vla-only/vla_only entries
all_vla_only = {}
current_exp = None
in_metrics = False

for i, line in enumerate(lines):
    # Check for experiment header
    if re.match(r'^  [a-z].*:', line):
        exp_match = re.match(r'^  (eval-[^:]*vla[_-]only[^:]*?):', line)
        if exp_match:
            current_exp = exp_match.group(1)
            all_vla_only[current_exp] = {
                'status': None,
                'sr': None,
                'conclusion': None,
                'line': i
            }
        else:
            current_exp = None
    elif current_exp:
        if 'status:' in line:
            match = re.search(r'status:\s*(\S+)', line)
            if match:
                all_vla_only[current_exp]['status'] = match.group(1)
        if 'success_rate:' in line or 'sr:' in line:
            match = re.search(r'(?:success_rate|sr):\s*([0-9.]+)', line)
            if match:
                all_vla_only[current_exp]['sr'] = match.group(1)

# Categorize and count
print("COMPLETE VLA-ONLY EXPERIMENT INVENTORY")
print("="*100)

benchmarks = {'object': [], 'spatial': [], 'goal': [], 'long': [], 'other': []}

for exp_id in sorted(all_vla_only.keys()):
    if 'object' in exp_id and 'spatial' not in exp_id:
        benchmarks['object'].append(exp_id)
    elif 'spatial' in exp_id:
        benchmarks['spatial'].append(exp_id)
    elif 'goal' in exp_id:
        benchmarks['goal'].append(exp_id)
    elif 'long' in exp_id:
        benchmarks['long'].append(exp_id)
    else:
        benchmarks['other'].append(exp_id)

for benchmark in ['object', 'spatial', 'goal', 'long', 'other']:
    exps = benchmarks[benchmark]
    if not exps:
        continue

    print(f"\n{benchmark.upper()} ({len(exps)})")
    print("-"*100)

    unique_seeds = set()
    status_counts = {}
    sr_values = []

    for exp_id in sorted(exps):
        info = all_vla_only[exp_id]
        status = info['status'] or '?'
        sr = info['sr'] or '?'

        status_counts[status] = status_counts.get(status, 0) + 1

        # Extract seed
        seed_match = re.search(r'seed(\d+)', exp_id)
        if seed_match:
            unique_seeds.add(int(seed_match.group(1)))

        # Track SR values
        if sr != '?':
            try:
                sr_values.append(float(sr))
            except:
                pass

        print(f"  {exp_id:50} | {status:10} | SR: {str(sr):6}")

    print(f"\nStatus breakdown: {status_counts}")
    if unique_seeds:
        print(f"Unique seeds ({len(unique_seeds)}): {sorted(unique_seeds)}")
    if sr_values:
        print(f"SR range: {min(sr_values):.2f} - {max(sr_values):.2f} (avg: {sum(sr_values)/len(sr_values):.2f})")

